<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';exigir_roles(['Administrador del sistema','Visualización y actualización']);csrf_validar();$id=(int)($_POST['id_neonato']??0);$peso=(int)($_POST['peso_actual_gramos']??0);$fecha=trim($_POST['fecha_estudio_programado']??'');$est=trim($_POST['estudios_proximos']??'');if($peso<200||$peso>8000||($fecha!==''&&strtotime($fecha)<strtotime(date('Y-m-d 00:00:00')))||($fecha!==''&&$est==='')){flash('error','Revisa el peso y la fecha/estudio programado.');redirigir('actualizar.php?id='.$id);}try{$q=$pdo->prepare('SELECT id_espacio FROM espacios_neonatales WHERE id_neonato=? AND estado_espacio=\'Ocupada\'');$q->execute([$id]);$sp=$q->fetch();if(!$sp)throw new RuntimeException('El neonato no tiene un espacio activo.');$q=$pdo->prepare('INSERT INTO estado_neonato(id_neonato,id_espacio,estado_clinico,soporte_respiratorio,alimentacion,atencion_especial,visitas,peso_actual_gramos,estudios_proximos,fecha_estudio_programado,observaciones_enfermeria_medica,actualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$id,$sp['id_espacio'],$_POST['estado_clinico'],$_POST['soporte_respiratorio'],$_POST['alimentacion'],$_POST['atencion_especial'],$_POST['visitas'],$peso,$est?:null,$fecha?str_replace('T',' ',$fecha):null,$_POST['observaciones_enfermeria_medica']??null,$_SESSION['id_usuario']]);registrar_bitacora($pdo,'estado_neonato',(string)$id,'INSERT',null,['peso_actual_gramos'=>$peso]);flash('ok','Actualización clínica guardada en el historial.');redirigir('index.php');}catch(Throwable $e){error_log('[SCUCIN enfermeria] '.$e->getMessage());flash('error','No fue posible guardar la actualización.');redirigir('actualizar.php?id='.$id);}
